import{_ as e,o,c as t,a2 as r}from"./chunks/framework.DaAAbehN.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"en/appendix/glossary.md","filePath":"en/appendix/glossary.md"}'),n={name:"en/appendix/glossary.md"};function i(s,a,l,h,d,c){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><hr><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="agent-智能体" tabindex="-1">Agent (智能体) <a class="header-anchor" href="#agent-智能体" aria-label="Permalink to &quot;Agent (智能体)&quot;">​</a></h3><p>A type of AI system that can autonomously perceive the environment, make decisions, and take actions. Codex is an AI programming agent — it can &quot;read files, write code, run commands&quot; instead of just answering questions passively.</p><h3 id="api-application-programming-interface" tabindex="-1">API (Application Programming Interface) <a class="header-anchor" href="#api-application-programming-interface" aria-label="Permalink to &quot;API (Application Programming Interface)&quot;">​</a></h3><p>Rules and protocols for communication between different software. For example, Codex communicates with OpenAI&#39;s servers through APIs to get AI capabilities.</p><hr><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="cli-command-line-interface" tabindex="-1">CLI (Command Line Interface) <a class="header-anchor" href="#cli-command-line-interface" aria-label="Permalink to &quot;CLI (Command Line Interface)&quot;">​</a></h3><p>A way to operate your computer by typing text commands, as opposed to a graphical interface (clicking with a mouse). Codex has a CLI version for advanced users.</p><h3 id="code-interpreter" tabindex="-1">Code Interpreter <a class="header-anchor" href="#code-interpreter" aria-label="Permalink to &quot;Code Interpreter&quot;">​</a></h3><p>A feature of ChatGPT that allows AI to run code you upload and return results. The core capability of the Codex desktop app is an enhanced version of the code interpreter.</p><hr><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="deep-learning" tabindex="-1">Deep Learning <a class="header-anchor" href="#deep-learning" aria-label="Permalink to &quot;Deep Learning&quot;">​</a></h3><p>A branch of machine learning that uses multi-layer neural networks to learn complex patterns in data. The technology behind Codex is based on deep learning.</p><hr><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h2><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><p>The world&#39;s largest code hosting platform, where developers share, collaborate on, and manage code projects.</p><hr><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="llm-large-language-model" tabindex="-1">LLM (Large Language Model) <a class="header-anchor" href="#llm-large-language-model" aria-label="Permalink to &quot;LLM (Large Language Model)&quot;">​</a></h3><p>Refers to language models with enormous numbers of parameters. ChatGPT, Codex, and others are all based on LLM technology.</p><h3 id="local-storage" tabindex="-1">Local Storage <a class="header-anchor" href="#local-storage" aria-label="Permalink to &quot;Local Storage&quot;">​</a></h3><p>A data storage method provided by browsers. Web pages can save data in the user&#39;s browser, and it won&#39;t be lost even after closing the page. The todo app in Project 3 relies on this for data persistence.</p><hr><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><h3 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Markdown&quot;">​</a></h3><p>A lightweight markup language that uses simple text symbols to represent formatting (e.g., <code>#</code> for headings, <code>**</code> for bold). This course uses Markdown as its content format.</p><h3 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h3><p>A standardized protocol that allows AI models to connect to external tools and data sources. Through MCP, Codex can access more external resources.</p><h3 id="machine-learning" tabindex="-1">Machine Learning <a class="header-anchor" href="#machine-learning" aria-label="Permalink to &quot;Machine Learning&quot;">​</a></h3><p>A branch of AI that enables computers to learn patterns from data without explicit programming.</p><hr><h2 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h2><h3 id="natural-language-processing-nlp" tabindex="-1">Natural Language Processing (NLP) <a class="header-anchor" href="#natural-language-processing-nlp" aria-label="Permalink to &quot;Natural Language Processing (NLP)&quot;">​</a></h3><p>Technology that enables computers to understand and generate human language. Codex can understand your Chinese or English instructions thanks to NLP technology.</p><hr><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="prompt-提示词-指令" tabindex="-1">Prompt (提示词/指令) <a class="header-anchor" href="#prompt-提示词-指令" aria-label="Permalink to &quot;Prompt (提示词/指令)&quot;">​</a></h3><p>The text instructions you input to AI. Good prompts get better results. The course emphasizes the importance of &quot;writing good prompts&quot; multiple times.</p><h3 id="python" tabindex="-1">Python <a class="header-anchor" href="#python" aria-label="Permalink to &quot;Python&quot;">​</a></h3><p>A widely used programming language with simple, readable syntax, very suitable for data processing, automation scripts, and other tasks. Much of the code Codex generates is in Python.</p><hr><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="rpa-robotic-process-automation" tabindex="-1">RPA (Robotic Process Automation) <a class="header-anchor" href="#rpa-robotic-process-automation" aria-label="Permalink to &quot;RPA (Robotic Process Automation)&quot;">​</a></h3><p>Using software robots to automatically execute repetitive tasks. Codex can be seen as an upgraded version of RPA — it&#39;s more flexible and doesn&#39;t require pre-designed workflows.</p><hr><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="sandbox-沙盒" tabindex="-1">Sandbox (沙盒) <a class="header-anchor" href="#sandbox-沙盒" aria-label="Permalink to &quot;Sandbox (沙盒)&quot;">​</a></h3><p>An isolated execution environment. Codex&#39;s workspace is a kind of &quot;sandbox&quot; — it can only operate on files within the workspace and won&#39;t affect other areas.</p><h3 id="session-会话" tabindex="-1">Session (会话) <a class="header-anchor" href="#session-会话" aria-label="Permalink to &quot;Session (会话)&quot;">​</a></h3><p>The complete process of one conversation. From when you open Codex and type the first message until you close the app, that&#39;s one session.</p><hr><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><h3 id="vibe-coding-氛围编程" tabindex="-1">Vibe Coding (氛围编程) <a class="header-anchor" href="#vibe-coding-氛围编程" aria-label="Permalink to &quot;Vibe Coding (氛围编程)&quot;">​</a></h3><p>A new programming philosophy: don&#39;t write code, instead describe the effect you want in natural language and let AI handle the implementation. This is the core teaching philosophy of this course.</p><hr><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><h3 id="workspace-工作区" tabindex="-1">Workspace (工作区) <a class="header-anchor" href="#workspace-工作区" aria-label="Permalink to &quot;Workspace (工作区)&quot;">​</a></h3><p>One of the most important concepts in Codex. The workspace is the file operation scope you designate to AI, like a &quot;safe sandbox&quot;.</p><hr><h2 id="📝-usage-tips" tabindex="-1">📝 Usage Tips <a class="header-anchor" href="#📝-usage-tips" aria-label="Permalink to &quot;📝 Usage Tips&quot;">​</a></h2><ul><li>This glossary uses plain language explanations, avoiding technical jargon</li><li>If a term appears multiple times in the text but you&#39;re still confused, check back in this glossary</li><li>Terms will be updated as technology advances. For the latest version, please refer to <a href="https://help.openai.com" target="_blank" rel="noreferrer">OpenAI Official Documentation</a></li></ul>',66)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
